    let etag = headers.get(header::ETAG).unwrap().to_str().unwrap();
    assert!(text.contains(&format!("<D:getetag>{etag}</D:getetag>")));
}

#[tokio::test]
async fn unknown_resource_and_cross_user_are_404() {
    let (
        _temp_dir,
        _pool,
        accounts,
        _user_id,
        password,
        principal_id,
        calendar_id,
        _event_id,
        _resource_name,
    ) = scenario().await;

    // Unknown resource name for the owner's calendar.
    let (status, _, _) = request(
        build_caldav_router(accounts.clone()),
        Method::GET,
        &format!("/dav/calendars/{principal_id}/{calendar_id}/does-not-exist.ics"),
        Some(("owner@example.test", &password)),
    )
    .await;
    assert_eq!(status, StatusCode::NOT_FOUND);

    // A different user cannot read the resource even with a valid name.
    let intruder_uri = format!(
        "/dav/calendars/{principal_id}/{calendar_id}/{unknown}.ics",
        unknown = "does-not-exist"
    );
    let (status, _, _) = request(
        build_caldav_router(accounts),
        Method::GET,
        &intruder_uri,
        None,
    )
    .await;
    assert_eq!(status, StatusCode::UNAUTHORIZED);
}

